<div class="branch-grid"><?php foreach($branches as $b): $d=$b['details'];?><article class="branch" data-search="<?=e(($d['city']??'').' '.($d['district']??'').' '.$b['title'])?>"><p class="eyebrow"><?=e($d['city']??'')?></p><h3><a href="<?=BASE?>/subeler/<?=e($b['slug'])?>"><?=e($b['title'])?></a></h3><p><?=e($d['address']??'')?></p><a class="branch-phone" href="tel:<?=e(preg_replace('/[^0-9+]/','',$d['phone']??''))?>"><?=e($d['phone']??'')?></a><div class="actions"><a class="button secondary" href="<?=BASE?>/subeler/<?=e($b['slug'])?>">Şubeyi incele</a><a class="text-link" href="<?=BASE?>/randevu?sube=<?=e($b['slug'])?>">Randevu al</a></div></article><?php endforeach;?></div><?php if(!$branches):?><p role="status">Şube bilgileri şu an gösterilemiyor. <a href="tel:+905527415143">Merkezimizi arayın.</a></p><?php endif;?>
